export function normalizeLegacySlug(slug: string) {
  return decodeURIComponent(slug).replace(/\/+$/, "").replace(/\.html$/i, "").toLowerCase();
}

export function findLegacyInsight(slug: string) {
  const normalizedSlug = normalizeLegacySlug(slug);

  return legacyInsights.find((article) => normalizeLegacySlug(article.slug) === normalizedSlug) ?? null;
}

export function getLegacyInsightParams() {
  return legacyInsights.flatMap((article) => [
    { slug: article.slug },
    { slug: article.slug.replace(/\.html$/i, "") },
  ]);
}
